package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.ai.*; import ca.yorku.eecs3311.coursepilot.application.dto.*; import ca.yorku.eecs3311.coursepilot.domain.model.*; import ca.yorku.eecs3311.coursepilot.domain.repository.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.Collectors;
@Service public class QuizAttemptService {
 private final QuizRepository quizzes; private final QuizAttemptRepository attempts; private final LlmClient llm; private final PromptBuilder prompts; private final StructuredResponseParser parser; private final GroundingContextBuilder builder; private final DocumentChunkRepository chunks;
 public QuizAttemptService(QuizRepository q,QuizAttemptRepository a,LlmClient l,PromptBuilder p,StructuredResponseParser s,GroundingContextBuilder b,DocumentChunkRepository c){quizzes=q;attempts=a;llm=l;prompts=p;parser=s;builder=b;chunks=c;}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public List<QuizResponseDto> list(Long courseId){return quizzes.findByCourseId(courseId).stream().map(QuizResponseDto::from).toList();}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public QuizResponseDto get(Long courseId,Long quizId){return QuizResponseDto.from(quizzes.findOwned(quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz was not found for this course.")));}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public List<QuizAttemptSummary> listAttempts(Long courseId,Long quizId){quizzes.findOwned(quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz was not found for this course."));return attempts.findByQuizId(quizId).stream().sorted(Comparator.comparing(QuizAttempt::getId,Comparator.nullsLast(Comparator.reverseOrder()))).map(a->new QuizAttemptSummary(a.getId(),a.getCorrectCount(),a.getTotalCount(),a.getCompletedAt())).toList();}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public QuizAttemptResult getAttempt(Long courseId,Long quizId,Long attemptId){QuizAttempt attempt=attempts.findOwned(attemptId,quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz attempt was not found for this course."));return toResult(attempt);}
 @Transactional public void delete(Long courseId,Long quizId){Quiz quiz=quizzes.findOwned(quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz was not found for this course."));attempts.deleteAll(attempts.findByQuizId(quizId));quizzes.delete(quiz);}
 @Transactional public QuizAttemptResult submit(Long courseId,Long quizId,Map<Long,String> answers){Quiz quiz=quizzes.findOwned(quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz was not found for this course."));Map<Long,String> submitted=answers==null?Map.of():answers;Set<Long> questionIds=quiz.getQuestions().stream().map(QuizQuestion::getId).collect(Collectors.toSet());if(!questionIds.containsAll(submitted.keySet()))throw new IllegalArgumentException("Quiz answers contain a question that does not belong to this quiz.");if(submitted.values().stream().anyMatch(value->value!=null&&value.length()>3000))throw new IllegalArgumentException("Quiz answer is too long.");QuizAttempt attempt=new QuizAttempt(quiz,quiz.getQuestions().size());List<QuizAttemptResult.AnswerResult> result=new ArrayList<>();int correct=0;for(QuizQuestion q:quiz.getQuestions()){String answer=Objects.toString(submitted.get(q.getId()),"").trim();Grading g=grade(q,answer);if(g.correct())correct++;attempt.addResponse(new QuizResponse(attempt,q,answer,g.correct(),g.feedback()));result.add(new QuizAttemptResult.AnswerResult(q.getId(),answer,g.correct(),g.feedback()));}attempt.finish(correct);QuizAttempt saved=attempts.save(attempt);return toResult(saved);}
 private QuizAttemptResult toResult(QuizAttempt attempt){return new QuizAttemptResult(attempt.getId(),attempt.getQuiz().getId(),attempt.getCorrectCount(),attempt.getTotalCount(),attempt.getResponses().stream().map(r->new QuizAttemptResult.AnswerResult(r.getQuestion().getId(),Objects.toString(r.getStudentAnswer(),""),r.isCorrect(),Objects.toString(r.getFeedback(),""))).toList());}
 private Grading grade(QuizQuestion q,String answer){if(answer.isBlank())return new Grading(false,"No answer was submitted.");if(q.getType()!=QuizQuestionType.SHORT_ANSWER){boolean correct=answer.equalsIgnoreCase(Objects.toString(q.getCorrectAnswer(),"").trim());return new Grading(correct,correct?"Your answer matches the expected answer.":explanationFor(q));}if(!llm.checkAvailability().isAvailable())return deterministic(q,answer,"AI grading is unavailable; this short answer was recorded for later review.");try{List<SearchResult> results=new ArrayList<>();for(QuizSource s:q.getSources()){var c=chunks.findById(s.getChunkId()).orElse(null);if(c!=null)results.add(new SearchResult(c.getDocument().getId(),c.getId(),c.getDocument().getOriginalFilename(),c.getChunkIndex(),c.getContent(),1d,c.getStartPage(),c.getEndPage(),List.of()));}var context=builder.build(results,12000);var parsed=parser.parse(llm.generate(prompts.buildShortAnswerGradingPrompt(q.getPrompt(),answer,q.getReferenceAnswer(),context.text())).content(),ShortAnswerGradingLlmResponse.class);Set<String> valid=context.sources().stream().map(GroundedSource::sourceId).collect(Collectors.toSet());if(parsed.feedback()==null||parsed.feedback().isBlank()||parsed.sourceIds().isEmpty()||parsed.sourceIds().stream().anyMatch(x->!valid.contains(x)))return deterministic(q,answer,"The AI grading response could not be validated; the answer was recorded.");return new Grading(parsed.correct(),parsed.feedback());}catch(RuntimeException ex){return deterministic(q,answer,"AI grading was unavailable; the answer was recorded safely.");}}
 private String explanationFor(QuizQuestion q){String explanation=q.getExplanation();if(explanation!=null&&!explanation.isBlank())return explanation;String reference=q.getReferenceAnswer();if(reference!=null&&!reference.isBlank())return reference;return "Review the correct answer and the concept being tested.";}
 private Grading deterministic(QuizQuestion q,String answer,String feedback){Set<String> ref=words(q.getReferenceAnswer()),given=words(answer);long overlap=given.stream().filter(ref::contains).count();return new Grading(!ref.isEmpty()&&overlap>=Math.max(1,Math.min(3,ref.size()/3)),feedback);}
 private Set<String> words(String value){return Arrays.stream(Objects.toString(value,"").toLowerCase(Locale.ROOT).split("[^a-z0-9]+" )).filter(x->x.length()>3).collect(Collectors.toSet());} private record Grading(boolean correct,String feedback){}
}
